insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('WinbackAI', 'winback-ai', 'Re-engage churned customers with the right message at the right time', 'WinbackAI analyzes why customers left, segments them by churn reason, and runs personalized re-engagement campaigns. It knows which customers are worth pursuing and what offer is likely to bring them back - saving your team from blanket discount blasts that erode margin.', 'https://example.com/winbackai', 'https://api.dicebear.com/7.x/shapes/svg?seed=winbackai&backgroundColor=fda4af', 'Customer Success', ARRAY['SaaS', 'E-commerce', 'Media', 'Finance'], ARRAY['HubSpot', 'Salesforce', 'Klaviyo', 'Gmail', 'Stripe'], 'usage_based', 'low', false, 3.9, 54);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ProspectPilot', 'prospect-pilot', 'Find your next 50 ideal customers while you sleep', 'ProspectPilot builds targeted prospect lists based on your ideal customer profile, enriches each contact with verified emails and LinkedIn profiles, and drafts personalized first-touch messages. Sales reps wake up to a ready-to-send outreach queue every morning.', 'https://example.com/prospectpilot', 'https://api.dicebear.com/7.x/shapes/svg?seed=prospectpilot&backgroundColor=bae6fd', 'Sales', ARRAY['SaaS', 'Professional Services', 'Finance', 'Tech'], ARRAY['Salesforce', 'HubSpot', 'LinkedIn', 'Gmail', 'Outreach', 'Apollo'], 'subscription', 'low', true, 4.5, 287);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('DealCoach', 'deal-coach', 'Get an honest read on every deal in your pipeline', 'DealCoach analyzes your CRM notes, email activity, and call transcripts to give each opportunity a health score and a clear next-best-action. It flags deals going cold before they are lost and surfaces the objections most likely to kill the close.', 'https://example.com/dealcoach', 'https://api.dicebear.com/7.x/shapes/svg?seed=dealcoach&backgroundColor=a7f3d0', 'Sales', ARRAY['SaaS', 'Finance', 'Real Estate', 'Professional Services'], ARRAY['Salesforce', 'HubSpot', 'Gong', 'Chorus', 'Gmail'], 'subscription', 'medium', true, 4.4, 198);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ExpenseEye', 'expense-eye', 'Catch wasteful spending before it hits the budget', 'ExpenseEye connects to your company credit cards and accounting software, categorizes every transaction automatically, and alerts you when spending trends are off. Finance teams use it to close the books faster and catch duplicate subscriptions, overspending, and policy violations.', 'https://example.com/expenseeye', 'https://api.dicebear.com/7.x/shapes/svg?seed=expenseeye&backgroundColor=fef08a', 'Finance', ARRAY['Finance', 'Operations', 'HR', 'Retail'], ARRAY['QuickBooks', 'Xero', 'NetSuite', 'Expensify', 'Ramp', 'Brex'], 'subscription', 'low', true, 4.3, 221);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ForecastAI', 'forecast-ai', 'Revenue forecasts you can actually trust', 'ForecastAI combines your historical sales data, pipeline, and seasonal patterns to produce rolling revenue forecasts that update automatically. Finance and sales leaders get a shared view of the number - no more spreadsheet wars or end-of-quarter surprises.', 'https://example.com/forecastai', 'https://api.dicebear.com/7.x/shapes/svg?seed=forecastai&backgroundColor=fbcfe8', 'Finance', ARRAY['SaaS', 'Finance', 'Retail', 'Manufacturing'], ARRAY['Salesforce', 'HubSpot', 'QuickBooks', 'NetSuite', 'Excel'], 'subscription', 'medium', false, 4.1, 89);
